style.css:
@-moz-document domain("discord.com") {
/* --- COLOR VARIABLES --- */
  :root {
    --hawks-red: #b11226;
    --hawks-dark-red: #7a0c1a;
    --hawks-gold: #f2b705;
    --hawks-black: #0e0e10;
    --hawks-gray: #1a1a1f;
    --hawks-light-gray: #2a2a32;
    --hawks-text: #e6e6e6;
  }

  /* --- BACKGROUND --- */
  body,
  .appMount-2yBXZl {
    background: linear-gradient(
      135deg,
      var(--hawks-black),
      var(--hawks-dark-red)
    ) !important;
  }

  /* --- MAIN APP BACKGROUND --- */
  .layers-3iHuyZ,
  .bg-1QIAus {
    background-color: transparent !important;
  }

  /* --- SIDEBAR (SERVERS + CHANNELS) --- */
  .guilds-2JjMmN,
  .sidebar-1tnWFu {
    background-color: var(--hawks-gray) !important;
    border-right: 2px solid var(--hawks-red);
  }

  /* --- SERVER ICON HOVER --- */
  .wrapper-3kah-n:hover {
    box-shadow: 0 0 10px var(--hawks-gold);
  }

  /* --- CHANNEL LIST --- */
  .containerDefault-YUSmu3:hover {
    background-color: rgba(242, 183, 5, 0.1) !important;
  }

  .modeSelected-3DmyhH {
    background: linear-gradient(
      90deg,
      var(--hawks-red),
      var(--hawks-gold)
    ) !important;
    color: #000 !important;
  }

  /* --- CHAT AREA --- */
  .chatContent-3KubbW {
    background-color: var(--hawks-black) !important;
  }

  /* --- MESSAGES --- */
  .message-2CShn3 {
    background-color: transparent !important;
  }

  .message-2CShn3:hover {
    background-color: rgba(177, 18, 38, 0.15) !important;
  }

  /* --- USERNAME COLORS --- */
  .username-h_Y3Us {
    color: var(--hawks-gold) !important;
  }

  /* --- INPUT BOX --- */
  .channelTextArea-1FufC0 {
    background-color: var(--hawks-light-gray) !important;
    border: 1px solid var(--hawks-red);
  }

  /* --- BUTTONS --- */
  button {
    background-color: var(--hawks-red) !important;
    color: #fff !important;
    border-radius: 6px;
  }

  button:hover {
    background-color: var(--hawks-gold) !important;
    color: #000 !important;
  }

  /* --- SCROLLBARS --- */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-thumb {
    background: linear-gradient(
      var(--hawks-red),
      var(--hawks-gold)
    );
    border-radius: 4px;
  }

